 48	function clinicCards(clinics) {
 49	  const root = $("clinics");
 50	  root.replaceChildren(node("h3", "Nearby veterinary care"));
 51	  if (!clinics.length) {
 52	    root.append(
 53	      node(
 54	        "p",
 55	        "No verified clinic results returned. Use the map search below or your usual vet’s contact number.",
 56	        "warning",
 57	      ),
 58	    );
 59	    return;
 60	  }
 61	  clinics.forEach((c) => {
 62	    const box = node("article", null, "panel clinic-card");
 63	    if (c.distance_km !== null)
 64	      box.append(node("span", c.distance_km + " km", "distance"));
 65	    box.append(node("h3", c.name), node("p", c.address));
 66	    const list = node("ul");
 67	    c.reasons.forEach((r) => list.append(node("li", r)));
 68	    box.append(list);
 69	    if (c.opening_hours.length) {
