 72	      c.opening_hours.forEach((h) => hours.append(node("div", h)));
 73	      box.append(hours);
 74	    }
 75	    const links = node("div", null, "input-actions");
 76	    if (c.call_url) links.append(action("Call clinic ↗", c.call_url));
 77	    if (c.maps_url) links.append(action("Map & directions ↗", c.maps_url));
 78	    if (c.website) links.append(action("Website ↗", c.website));
 79	    box.append(
 80	      links,
 81	      node("p", c.availability_note, "small"),
 82	      node(
 83	        "p",
 84	        "Source: " +
 85	          c.source.replaceAll("_", " ") +
 86	          " · Retrieved " +
 87	          new Date(c.retrieved_at).toLocaleTimeString(),
 88	        "small",
 89	      ),
 90	    );
 91	    if (c.source === "google_places" || c.source === "gemini_maps") {
 92	      const attribution = node("p", null, "small maps-attribution");
 93	      const link = action("Google Maps", c.maps_url || "https://maps.google.com");
 94	      link.setAttribute("translate", "no");
 95	      attribution.append(link);
 96	      box.append(attribution);
 97	    } else if (c.source === "openstreetmap") {
 98	      box.append(node("p", "© OpenStreetMap contributors (ODbL)", "small"));
 99	    }
100	    root.append(box);
101	  });
102	}
