118	function handleEvent(e) {
119	  if (e.type === "safety" || e.type === "assessment")
120	    assessmentCard(e.assessment);
121	  if (e.type === "insurance") insuranceCard(e.insurance);
122	  if (e.type === "clinics") clinicCards(e.clinics);
123	  if (e.type === "progress")
124	    $("progress").textContent = (names[e.agent] || e.agent) + " · " + e.status;
125	  if (e.type === "result") {
