154	}
155	async function stream(url, payload, onEvent) {
156	  const r = await fetch(url, {
157	    method: "POST",
158	    headers: { "Content-Type": "application/json" },
159	    body: JSON.stringify(payload),
160	  });
161	  if (!r.ok) {
162	    let error;
163	    try {
164	      error = await r.json();
165	    } catch {}
166	    throw Error(
167	      typeof error?.detail === "string"
168	        ? error.detail
169	        : error?.error?.fields?.map((x) => x.message).join("; ") ||
170	            "Request failed. Please check your inputs and try again.",
171	    );
172	  }
173	  const reader = r.body.getReader(),
174	    decoder = new TextDecoder();
175	  let buffer = "";
176	  try {
177	    while (true) {
178	      const { value, done } = await reader.read();
179	      buffer += decoder.decode(value || new Uint8Array(), { stream: !done });
180	      let index;
181	      while ((index = buffer.indexOf("\n\n")) >= 0) {
182	        const chunk = buffer.slice(0, index);
183	        buffer = buffer.slice(index + 2);
184	        const data = chunk
185	          .split("\n")
186	          .filter((x) => x.startsWith("data:"))
187	          .map((x) => x.slice(5).trim())
188	          .join("\n");
189	        if (data) onEvent(JSON.parse(data));
190	      }
191	      if (done) break;
192	    }
193	  } finally {
194	    reader.releaseLock();
195	  }
196	}
197	$("photo").onchange = async () => {
198	  const file = $("photo").files[0];
199	  if (!file) return;
200	  if (
201	    file.size > 3000000 ||
202	    !["image/jpeg", "image/png", "image/webp"].includes(file.type)
203	  ) {
204	    photo = null;
205	    $("photo").value = "";
206	    $("photo-preview").hidden = true;
207	    $("remove-photo").hidden = true;
208	    $("photo-status").textContent =
209	      "Please choose a JPEG, PNG or WebP up to 3 MB.";
210	    return;
211	  }
212	  const data = await new Promise((resolve, reject) => {
213	    const r = new FileReader();
214	    r.onload = () => resolve(r.result);
215	    r.onerror = reject;
216	    r.readAsDataURL(file);
217	  });
218	  photo = { mime_type: file.type, data: data.split(",")[1] };
219	  $("photo-preview").src = data;
220	  $("photo-preview").hidden = false;
221	  $("remove-photo").hidden = false;
222	  $("photo-status").textContent =
223	    "Photo selected. Shared only when you enable AI assistance.";
224	};
