254	$("care-form").onsubmit = async (e) => {
255	  e.preventDefault();
256	  if (busy) return;
257	  requestId = null;
258	  busy = true;
259	  $("submit").disabled = true;
260	  $("handoff").hidden = true;
261	  $("clinics").replaceChildren();
262	  $("limitations").replaceChildren();
263	  $("agent-run-trace").hidden = true;
264	  $("agent-trace-list").replaceChildren();
265	  $("progress").textContent = "Preparing your next steps…";
266	  const insurer = $("insurer").value.trim(),
267	    phone = $("insurance-phone").value.trim();
268	  try {
269	    if (Boolean(insurer) !== Boolean(phone))
270	      throw Error(
271	        "Enter both the insurer and its international phone number, or leave both blank.",
272	      );
273	    const payload = {
274	      query: $("query").value,
275	      cat_name: $("cat-name").value,
276	      location: { lat: Number($("lat").value), lng: Number($("lng").value) },
277	      radius_km: Number($("radius").value),
278	      language: $("care-language").value,
279	      red_flags: [...document.querySelectorAll("#red-flags input:checked")].map(
280	        (i) => i.value,
281	      ),
282	      photo,
283	      insurance: insurer
284	        ? { company: insurer, phone, plan: $("insurance-plan").value.trim() || null }
285	        : null,
286	      share_with_ai: $("ai-consent").checked,
287	      share_location: $("location-consent").checked,
288	    };
289	    if ($("agent-workflow").checked) {
290	      $("progress").textContent =
291	        "Coordinating care guidance and clinic retrieval. The agent results will appear when the workflow finishes…";
292	      const response = await fetch("/api/v1/agents/runs", {
293	        method: "POST",
294	        headers: { "Content-Type": "application/json" },
295	        body: JSON.stringify({ care: payload }),
296	        signal: AbortSignal.timeout(60000),
297	      });
298	      const result = await response.json();
299	      if (!response.ok)
300	        throw Error(
301	          typeof result.detail === "string"
302	            ? result.detail
303	            : result.error?.fields?.map((field) => field.message).join("; ") ||
304	                "The agent workflow could not finish. Check your inputs and try again.",
305	        );
306	      handleEvent({ ...result.care, type: "result" });
307	      renderAgentTrace(result);
308	    } else {
309	      await stream("/api/v1/care/requests?stream=true", payload, handleEvent);
310	    }
311	  } catch (err) {
312	    $("progress").textContent = err.message;
313	  } finally {
314	    busy = false;
315	    $("submit").disabled = false;
316	  }
317	};
