531	function coverageDetail(details) {
532	  const parts = [];
533	  if (details.annual_limit_chf) parts.push(chf(details.annual_limit_chf) + " a year");
534	  if (details.limit_chf_per_day)
535	    parts.push(chf(details.limit_chf_per_day) + " a day, up to " + details.max_days_per_year + " days");
536	  if (details.includes) parts.push(details.includes.map(label).join(", "));
537	  return parts.join(" · ");
538	}
