174	    try {
175	      decoded = await context.decodeAudioData(await blob.arrayBuffer());
176	    } finally {
177	      await context.close();
178	    }
179	    const min = kind === "sample" ? 10 : 0.5;
180	    const max = kind === "sample" ? 30 : 60;
181	    if (decoded.duration < min || decoded.duration > max)
182	      throw Error(
183	        `Use ${min}–${max} seconds of audio. This recording is ${decoded.duration.toFixed(1)} seconds.`,
184	      );
185	    const rate = 24000;
186	    const offline = new OfflineAudioContext(
187	      1,
188	      Math.ceil(decoded.duration * rate),
189	      rate,
190	    );
191	    const source = offline.createBufferSource();
192	    source.buffer = decoded;
193	    source.connect(offline.destination);
194	    source.start();
195	    const samples = (await offline.startRendering()).getChannelData(0);
196	    const buffer = new ArrayBuffer(44 + samples.length * 2);
197	    const view = new DataView(buffer);
198	    const word = (offset, text) =>
199	      [...text].forEach((char, i) =>
200	        view.setUint8(offset + i, char.charCodeAt(0)),
201	      );
202	    word(0, "RIFF");
203	    view.setUint32(4, 36 + samples.length * 2, true);
204	    word(8, "WAVE");
205	    word(12, "fmt ");
206	    view.setUint32(16, 16, true);
207	    view.setUint16(20, 1, true);
208	    view.setUint16(22, 1, true);
209	    view.setUint32(24, rate, true);
210	    view.setUint32(28, rate * 2, true);
211	    view.setUint16(32, 2, true);
212	    view.setUint16(34, 16, true);
213	    word(36, "data");
214	    view.setUint32(40, samples.length * 2, true);
215	    for (let i = 0; i < samples.length; i++) {
216	      const v = Math.max(-1, Math.min(1, samples[i]));
217	      view.setInt16(44 + i * 2, v < 0 ? v * 0x8000 : v * 0x7fff, true);
218	    }
